'use strict';
const $=s=>document.querySelector(s), app=$('#app'), dialog=$('#dialog');
const KEY='kotoba-garden-v1', VERB_EDITION='school-50-two-panel';let saved={scores:{},rate:.8,auto:false,voice:''}, storageOK=true;
try{const p=JSON.parse(localStorage.getItem(KEY)||'null');if(p&&typeof p==='object')saved={...saved,...p,scores:p.scores||{}}}catch(e){storageOK=false}
if(saved.verbEdition!==VERB_EDITION){
 saved.previousVerbScores={...(saved.previousVerbScores||{}),...Object.fromEntries(Object.entries(saved.scores).filter(([k])=>k.startsWith('verb-')))};
 saved.scores=Object.fromEntries(Object.entries(saved.scores).filter(([k])=>!k.startsWith('verb-')));
 saved.verbEdition=VERB_EDITION;
 try{localStorage.setItem(KEY,JSON.stringify(saved))}catch(e){storageOK=false}
}
let state={page:'home',kind:'verb',mode:'mix',round:0,questions:[],index:0,answers:[],locked:false,review:false};
const bank=k=>k==='verb'?VERBS:NOUNS, total=k=>k==='verb'?30:50, label=k=>k==='verb'?'うごきのことば':'もののことば';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved))}catch(e){storageOK=false;toast('きろくを ほぞんできません。この まま あそべます。')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function scene(w){return `<span class="scene ${w.art?'':'emoji'} ${w.sequence?'sequence':''}" aria-hidden="true">${w.art||w.emoji}</span>`}
function sound(text,aria='おとを きく'){return `<button class="speaker" data-say="${esc(text)}" aria-label="${esc(aria)}" title="${esc(aria)}">♫</button>`}
function voices(){return 'speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>/^ja(?:-|_)/i.test(v.lang)||v.lang==='ja'):[]}
function speak(text){if(!('speechSynthesis'in window)){toast('この ブラウザでは おとが でません。せんせいに きいてね。');return}const list=voices();if(!list.length){toast('にほんごの おんせいが ありません。せっていを かくにんしてね。');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.voice=list.find(v=>v.name===saved.voice)||list[0];u.rate=Number(saved.rate)||.8;u.pitch=1;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('おとが でませんでした。もういちど おしてね。')};speechSynthesis.speak(u)}
if('speechSynthesis'in window){speechSynthesis.getVoices();speechSynthesis.addEventListener('voiceschanged',()=>{if(dialog.open&&dialog.dataset.type==='settings')settings()})}
function rng(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}}
function shuffle(a,r=Math.random){const b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
// Fixed coverage: each verb appears 6 times; each noun twice. Mixed mode alternates directions across repeats.
const OVERLAP_GROUPS=[
 ['かく','えがく'],['くばる','わたす','うけとる','あつめる'],
 ['いれる','すてる'],['もつ','はこぶ'],
 ['かたづける','いれる','だす','あつめる','おく','ならべる'],
 ['ほん','のーと'],['くつ','ながぐつ','さんだる'],['かばん','りゅっく'],
 ['まめ','ぴーなっつ'],['にく','ぎょうざ'],['さかな','さめ'],['くるま','ばす','とらっく','きゅうきゅうしゃ','しょうぼうしゃ','ぱとかー','たくしー']
];
function isCompatible(a,b,kind){
 if(a.id===b.id||a.word===b.word||(a.art||a.emoji)===(b.art||b.emoji))return false;
 if(OVERLAP_GROUPS.some(g=>g.includes(a.word)&&g.includes(b.word)))return false;
 if(kind==='verb'){
  // A standing person can also be eating, holding or talking; don't ask children to choose between these readings.
  if(b.word==='たつ'&& !['すわる','ねる','おきる','とぶ','およぐ'].includes(a.word))return false;
  if(a.word==='たつ'&& !['すわる','ねる','おきる','とぶ','およぐ','ぬぐ','きる','あける','しめる','ひろう','おじぎをする'].includes(b.word))return false;
  if(b.word==='もつ'&&a.word!=='もつ')return false;
 }
 return true;
}
function makeQuestions(kind,round,mode='mix'){
 const all=bank(kind), r=rng((kind==='verb'?321:8751)+round*137), size=all.length;
 return Array.from({length:10},(_,j)=>{const pos=round*10+j, cycle=Math.floor(pos/size), wi=pos%size, target=all[wi];const direction=mode==='mix'?((wi+cycle)%2?'picture':'text'):mode;
 const pool=all.filter(w=>isCompatible(target,w,kind));
 const framePool=kind==='verb'?pool.filter(w=>!!w.sequence===!!target.sequence):pool;
 const candidates=framePool.length>=3?framePool:pool;

 const same=shuffle(candidates.filter(w=>w.g===target.g),r),other=shuffle(candidates.filter(w=>w.g!==target.g),r);const distract=[...same,...other].slice(0,3);
 return {target,direction,options:shuffle([target,...distract],r)};
 });
}
function done(k){return Object.keys(saved.scores).filter(x=>x.startsWith(k+'-')).length}
function render(){app.innerHTML=state.page==='home'?homeHTML():state.page==='rounds'?roundsHTML():state.page==='quiz'?quizHTML():resultHTML();window.scrollTo({top:0,behavior:'instant'})}
function homeHTML(){return `<section class="intro"><div><div class="eyebrow">え と おと で、にほんご。</div><h1>きょうは なにを<br>おぼえよう？</h1><p>みて、きいて、えらんでみよう。<br>10もんずつ、じぶんの ペースで。</p></div><div class="mascot-scene" aria-hidden="true"><span class="sun">✳</span><div class="cloud"></div><div class="hill"></div><div class="mascot"><span class="leaf"></span></div><span class="sprout">🌱</span><div class="bubble">いっしょに やろう！</div></div></section><div class="section-label">すきな ことばを えらぼう</div><section class="path-cards"><button class="path-card" data-action="rounds" data-kind="verb"><div class="card-top"><span class="pill">うごき · 30コース</span></div><div class="card-art">${VERBS[2].art}</div><h2>うごきのことば</h2><p class="card-desc">たべる・あるく・あそぶ</p><div class="card-bottom"><span>1コース 10もん　 ·　${done('verb')} / 30 おわり</span><span class="go">↗</span></div></button><button class="path-card noun" data-action="rounds" data-kind="noun"><div class="card-top"><span class="pill">もの · 50コース</span></div><div class="card-art noun-art" aria-hidden="true"><span>🍎</span><span>✏️</span><span>🐱</span><span>🌷</span></div><h2>もののことば</h2><p class="card-desc">りんご・えんぴつ・ねこ</p><div class="card-bottom"><span>1コース 10もん　 ·　${done('noun')} / 50 おわり</span><span class="go">↗</span></div></button></section><section class="help-strip"><div class="help-row"><span class="help-icon">♫</span><div><strong>おとを きいてみよう</strong><p>♫ を おすと、にほんごが きこえるよ。</p></div></div><button class="sound-large" data-action="soundtest">♫ おとを ためす</button></section><div class="stats-row"><span>🌱 おわった コース <strong>${done('verb')+done('noun')}</strong> / 80</span><span>✦ まちがえても だいじょうぶ</span></div>${!storageOK?'<p class="notice">この ブラウザでは きろくが のこりません。</p>':''}`}
function roundsHTML(){const k=state.kind;return `<button class="back" data-action="home">← はじめに もどる</button><div class="page-head"><div><div class="eyebrow">${k==='verb'?'🌿':'🍎'} ことばを そだてよう</div><h2>${label(k)}</h2><p>コースを えらんでね。どこからでも はじめられるよ。</p></div><span class="round-count">${done(k)} / ${total(k)} おわり</span></div><div class="mode-bar" aria-label="もんだいの かたち">${[['mix','まぜて れんしゅう'],['text','え → ことば'],['picture','ことば → え']].map(([m,l])=>`<button data-action="mode" data-mode="${m}" class="${state.mode===m?'active':''}" aria-pressed="${state.mode===m}">${l}</button>`).join('')}</div><div class="round-grid">${Array.from({length:total(k)},(_,i)=>{const score=saved.scores[k+'-'+i];return `<button class="round ${score?'done':''}" data-action="start" data-round="${i}" aria-label="コース ${i+1}${score?'、'+score.best+'もん せいかい':''}"><small>コース</small><span class="num">${String(i+1).padStart(2,'0')}</span><small>${k==='noun'?esc(bank(k)[i*10%bank(k).length].g):'うごきを おぼえよう'}</small><div class="stars">${score?`${score.best===10?'✦ ✦ ✦':'✓'}　${score.best}/10`:'· · ·'}</div></button>`}).join('')}</div><p class="course-note">${k==='verb'?'50この ことばを、6かいずつ れんしゅうするよ。':'250この ことばを、2かいずつ れんしゅうするよ。'}<br>きろくは この ブラウザに のこるよ。</p>`}
function start(round,reviewQuestions){state.round=round;state.page='quiz';state.index=0;state.answers=[];state.locked=false;state.review=!!reviewQuestions;state.questions=reviewQuestions||makeQuestions(state.kind,round,state.mode);render();autoSpeak()}
function autoSpeak(){if(saved.auto&&state.page==='quiz'){const q=state.questions[state.index];speak(q.direction==='picture'?q.target.word:'えに あう ことばを えらぼう')}}
function quizHTML(){const q=state.questions[state.index],pic=q.direction==='picture',instruction=pic?'ことばに あう えを えらぼう':'えに あう ことばを えらぼう';const answer=state.answers[state.index];const hasSequence=pic?q.options.some(w=>w.sequence):q.target.sequence;return `<div class="quiz-top"><button class="back" data-action="exit">← コース</button><div class="progress" role="progressbar" aria-label="すすみぐあい" aria-valuemin="0" aria-valuemax="${state.questions.length}" aria-valuenow="${state.index}"><div style="width:${state.index/state.questions.length*100}%"></div></div><span>${state.index+1} / ${state.questions.length}</span></div><h2 class="question-title">${instruction}${sound(instruction,'もんだいの せつめいを きく')}</h2>${hasSequence?'<p class="sequence-hint">1 → 2 の じゅんに みてね</p>':''}<div class="prompt-card">${pic?`<span class="word">${q.target.word}</span>${sound(q.target.word,'もんだいの ことばを きく')}`:scene(q.target)}</div><div class="choices">${q.options.map((w,i)=>{const cls=answer?(w.id===q.target.id?'correct':w.id===answer.chosen?'wrong':'dim'):'';return `<div class="choice ${pic?'picture':''} ${cls}"><button class="answer" data-action="answer" data-id="${w.id}" ${state.locked?'disabled':''} aria-label="${pic?'え '+(i+1):w.word}"><span class="index">${i+1}</span>${pic?scene(w):esc(w.word)}</button>${!pic?sound(w.word,`${i+1}ばんの ことばを きく`):''}</div>`}).join('')}</div>${answer?`<div class="feedback ${answer.correct?'good':'try'}" role="status"><div><strong>${answer.correct?'◎ せいかい！':'もう ひといき！'}</strong><small>こたえは「${q.target.word}」${q.target.note?' · '+q.target.note:''}</small></div>${sound(q.target.note||q.target.word,'こたえを きく')}<button class="primary" data-action="next">${state.index===state.questions.length-1?'けっかを みる':'つぎへ'} →</button></div>`:'<div class="feedback"><small style="color:var(--muted);margin:auto">'+(pic?'えを おして えらんでね。':'♫ で きいてから えらんでも いいよ。')+'</small></div>'}`}
function answer(id){if(state.locked)return;const q=state.questions[state.index];if(!q.options.some(w=>w.id===id))return;state.answers.push({chosen:id,correct:id===q.target.id});state.locked=true;render();if(saved.auto)speak(id===q.target.id?'せいかい。'+q.target.word:'こたえは、'+q.target.word)}
function next(){if(!state.locked)return;if(state.index<state.questions.length-1){state.index++;state.locked=false;render();autoSpeak()}else{if(!state.review){const score=state.answers.filter(a=>a.correct).length,key=state.kind+'-'+state.round;const old=saved.scores[key];saved.scores[key]={best:Math.max(old?.best||0,score),last:score,attempts:(old?.attempts||0)+1,date:new Date().toISOString()};persist()}state.page='result';render()}}
function resultHTML(){const score=state.answers.filter(a=>a.correct).length,miss=state.answers.length-score;return `<section class="result"><div class="eyebrow">${state.review?'もういちど れんしゅう':'コース '+(state.round+1)} おわり！</div><div class="result-plant" aria-hidden="true">${score===state.questions.length?'🌻':'🌱'}</div><h1>${score===state.questions.length?'ぜんぶ できたね！':'よく がんばったね！'}</h1><div class="score">${score}<small> / ${state.questions.length} もん</small></div><p>きょうも ことばが ふえたね。</p><div class="result-actions">${miss?'<button class="primary" data-action="review">まちがえた もんだいを もういちど</button>':!state.review&&state.round+1<total(state.kind)?'<button class="primary" data-action="nextRound">つぎの コースへ →</button>':''}<button class="secondary" data-action="retry">もういちど</button><button class="secondary" data-action="rounds">コースに もどる</button></div><div class="section-label">れんしゅうした ことば</div><div class="result-list">${state.questions.map((q,i)=>`<div class="mini-word"><span class="status-dot">${state.answers[i].correct?'◎ できた':'↻ もういちど'}</span>${scene(q.target)}<p>${q.target.word}</p>${sound(q.target.note||q.target.word)}</div>`).join('')}</div></section>`}
function showDialog(title,html,type){dialog.dataset.type=type;dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="とじる">×</button></div><div class="dialog-content">${html}</div>`;if(!dialog.open)dialog.showModal()}
function settings(){const vs=voices();showDialog('せってい',`<div class="setting"><label>よむ はやさ<select id="rate"><option value="0.65" ${saved.rate==.65?'selected':''}>もっと ゆっくり</option><option value="0.8" ${saved.rate==.8?'selected':''}>ゆっくり</option><option value="1" ${saved.rate==1?'selected':''}>ふつう</option></select></label></div><div class="setting"><label>にほんごの こえ<select id="voice"><option value="">おまかせ</option>${vs.map(v=>`<option value="${esc(v.name)}" ${saved.voice===v.name?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><p>${vs.length?'日本語音声が '+vs.length+' 件見つかりました。':'日本語音声が見つかりません。端末の言語・読み上げ設定で日本語音声を追加してください。'}</p></div><div class="setting"><label>じどうで おとを きく<input type="checkbox" id="auto" ${saved.auto?'checked':''}></label><p>問題と答えを読み上げます。音声ボタンで何度でも聞けます。</p></div><div class="dialog-actions"><button class="primary" data-action="soundtest">♫ おとを ためす</button><button class="secondary" data-action="teacher">せんせいへ</button></div>`,'settings')}
function teacher(){showDialog('せんせいへ',`<p><b>イラストと音声で学ぶ、初級の日本語。</b><br>動詞50語 × 6回＝300問（30コース）<br>名詞250語 × 2回＝500問（50コース）<br>1コース10問・4択。新しく「ならぶ・くばる・はこぶ・かたづける」など学校で使う動詞を加えました。全コース最初から選べます。「まぜて」では2形式を5問ずつ出題します。</p><div class="notice"><b>音声について</b><br>端末・ブラウザに搭載された日本語の合成音声を使用します。授業前に児童が使う端末で「おとを ためす」を確認してください。声や発音は端末によって異なります。日本語音声がない場合、設定から追加が必要です。録音済みの音声ではありません。</div><p>ひらがなで表示します（外来語も初期学習用にひらがな・長音符で表記）。動詞は動作の図で示します。2コマの図は1→2の順に見ます。名詞は絵文字と図で示します。絵文字の見え方は端末によって異なります。迷いやすい図は授業前にご確認ください。モンゴル語訳は収録していません。</p><div class="notice"><b>学習記録</b><br>動詞50語版ではコース内容が変わるため、旧動詞コースの点数は別に保管し、新しい達成数には含めません。名詞コースの記録は引き継ぎます。<br>このブラウザに最高点・直近の点数・挑戦回数を保存します。氏名は入力しません。児童別の記録や端末間の同期はありません。共用端末では記録も共用になります。ブラウザのデータを消すと記録も消えます。</div><div class="dialog-actions"><button class="primary" data-action="vocab">ことばの 一覧（300語）</button><button class="secondary" data-action="settings">音声の 設定</button><button class="secondary" data-action="previousScores">以前の 動詞の 記録</button><button class="secondary" data-action="resetConfirm">記録を リセット</button></div>`,'teacher')}
function vocab(filter=''){const words=[...VERBS,...NOUNS].filter(w=>w.word.includes(filter)||w.g.includes(filter));showDialog('ことばの 一覧',`<input class="search" id="search" placeholder="ことば・なかまを さがす" value="${esc(filter)}" aria-label="ことばを さがす"><div class="vocabulary">${words.map(w=>`<div class="vocab-item">${scene(w)}<span>${w.word}<small>${w.note||w.g}</small></span>${sound(w.note||w.word)}</div>`).join('')}</div>`,'vocab')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.say){speak(b.dataset.say);return}const a=b.dataset.action;switch(a){case'home':if(state.page==='quiz'){showDialog('おわりに する？','<p>とちゅうの コースは ほぞんされないよ。</p><div class="dialog-actions"><button class="primary" data-action="confirmHome">はじめに もどる</button><button class="secondary" data-action="close">つづける</button></div>','exit');break}state.page='home';render();break;case'confirmHome':dialog.close();state.page='home';render();break;case'rounds':if(b.dataset.kind)state.kind=b.dataset.kind;state.page='rounds';render();break;case'mode':state.mode=b.dataset.mode;render();break;case'start':start(Number(b.dataset.round));break;case'answer':answer(b.dataset.id);break;case'next':next();break;case'retry':start(state.round,state.review?state.questions:null);break;case'nextRound':start(state.round+1);break;case'review':start(state.round,state.questions.filter((_,i)=>!state.answers[i].correct));break;case'exit':showDialog('コースに もどる？','<p>とちゅうの コースは ほぞんされないよ。</p><div class="dialog-actions"><button class="primary" data-action="confirmExit">コースに もどる</button><button class="secondary" data-action="close">つづける</button></div>','exit');break;case'confirmExit':dialog.close();state.page='rounds';render();break;case'soundtest':speak('こんにちは。いっしょに、にほんごを、べんきょうしましょう。');break;case'settings':settings();break;case'teacher':teacher();break;case'vocab':vocab();break;case'close':dialog.close();break;case'previousScores':showDialog('以前の 動詞の 記録',Object.keys(saved.previousVerbScores||{}).length?Object.entries(saved.previousVerbScores).map(([key,v])=>'<p>コース '+(Number(key.split('-')[1])+1)+'：最高 '+v.best+'/10・'+v.attempts+'回</p>').join(''):'<p>以前の 記録は ありません。</p>','previous');break;case'resetConfirm':showDialog('記録を消しますか？','<p>このブラウザに保存した全コースの点数・挑戦回数と、以前の動詞の記録を消します。元に戻せません。</p><div class="dialog-actions"><button class="primary" data-action="reset">記録を 消す</button><button class="secondary" data-action="teacher">やめる</button></div>','reset');break;case'reset':saved.scores={};saved.previousVerbScores={};persist();dialog.close();render();toast('きろくを リセットしました。');break;}});
document.addEventListener('change',e=>{if(e.target.id==='rate')saved.rate=Number(e.target.value);else if(e.target.id==='voice')saved.voice=e.target.value;else if(e.target.id==='auto')saved.auto=e.target.checked;else return;persist()});
document.addEventListener('input',e=>{if(e.target.id==='search'){const value=e.target.value,pos=e.target.selectionStart;vocab(value);$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
render();
